        return [[m.group(1), m.end() - m.start()]
                for m in re.finditer(r'(.)\1*', s, re.DOTALL)]
    # Generic fallback for any iterable of characters.
    return [[ch, sum(1 for _ in grp)] for ch, grp in groupby(s)]
