def solve(a: str, b: str) -> int:
    # Use O(min(len(a), len(b))) space DP for Levenshtein distance
    if len(a) < len(b):
        a, b = b, a  # ensure a is longer
    m, n = len(a), len(b)
    # previous and current rows
    prev = list(range(n + 1))
    curr = [0] * (n + 1)
    for i in range(1, m + 1):
        curr[0] = i
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                cost = 0
            else:
                cost = 1
            # deletion (prev[j] + 1), insertion (curr[j-1] + 1), substitution (prev[j-1] + cost)
            curr[j] = min(prev[j] + 1, curr[j-1] + 1, prev[j-1] + cost)
        prev, curr = curr, prev  # swap references
    return prev[n]

